from template_utils import (
    load_ideal_title_page,
    add_heading_1,
    add_heading_2,
    add_paragraph,
    add_toc,
    save_report
)


def generate() -> str:
    """
    Генерирует академический доклад по истории автомобилей.
    """
    topic = "История автомобилей: от первых паровых тележек до автономных электромобилей"
    discipline = "История науки и техники"

    # 1. Загрузка идеального титульного листа из эталонного шаблона
    doc = load_ideal_title_page(topic=topic, discipline=discipline)
    doc.add_page_break()

    # 2. Чистое автоматическое оглавление
    add_toc(doc)
    doc.add_page_break()

    # 3. ВВЕДЕНИЕ
    add_heading_1(doc, "Введение")
    add_paragraph(doc, "Возникновение и эволюция автомобиля представляют собой один из наиболее фундаментальных процессов в истории технического прогресса человечества. За чуть более чем 200 лет самоходный экипаж проделал путь от громоздкой паровой машинно-колесной платформы с крайне низким коэффициентом полезного действия до интеллектуального высокоэкологичного транспортного средства, управляемого алгоритмами искусственного интеллекта.")
    add_paragraph(doc, "Актуальность темы исследования обусловлена тем, что современная автомобильная промышленность стоит на пороге смены технологического уклада: происходит глобальный переход от двигателей внутреннего сгорания к электрическим силовым установкам и системам автономного вождения. Понимание исторических этапов, инженерных закономерностей и кривых развития автомобильной техники позволяет адекватно оценить вектор её дальнейшей трансформации.")
    add_paragraph(doc, "Объектом исследования является автомобильный транспорт как комплексная техническая система. Предметом исследования выступает историко-техническая эволюция конструкций, силовых агрегатов, производственных процессов и систем безопасности автомобилей с XVIII по XXI век.")
    add_paragraph(doc, "Целью данной работы является системный анализ основных этапов развития автомобилестроения, выявление ключевых научно-инженерных открытий и оценка их влияния на современный автопром.")
    add_paragraph(doc, "Для достижения поставленной цели потребовалось решить следующие задачи:")
    add_paragraph(doc, "1. Изучить ранний период создания самоходных экипажей на паровой тяге и оценить их конструктивные ограничения.")
    add_paragraph(doc, "2. Проанализировать процесс изобретения двигателя внутреннего сгорания и становления первых бензиновых автомобилей (работы К. Бенца, Г. Даймлера, В. Майбаха).")
    add_paragraph(doc, "3. Исследовать промышленную революцию Генри Форда, внедрение конвейерной сборки и становление массового автопрома.")
    add_paragraph(doc, "4. Проследить развитие систем активной и пассивной безопасности, аэродинамики и топливной экономичности во второй половине XX века.")
    add_paragraph(doc, "5. Оценить современные тенденции XXI века: электрификацию, цифровизацию и внедрение автономного управления (уровни SAE).")
    add_paragraph(doc, "Методологическую основу работы составили методы историко-генетического, системно-структурного и сравнительно-технического анализа профильной научно-технической литературы и архивных патентов.")
    doc.add_page_break()

    # 4. ГЛАВА 1
    add_heading_1(doc, "Глава 1. Истоки автомобилестроения и эпоха пара (XVII–XIX вв.)")
    add_heading_2(doc, "1.1 Первые теоретические концепции и паровая тележка Николя-Жозефа Кюньо")
    add_paragraph(doc, "Предыстория автомобилестроения уходит корнями в попытки человечества создать сухопутное средство передвижения, не требующее мускульной силы животных. Первые теоретические эскизы самоходных повозщиков встречаются в работах Леонардо да Винчи (концепция пружинного привода, ок. 1478 г.) и Фердинанда Вербиста (паровая модель для китайского императора, 1672 г.).")
    add_paragraph(doc, "Практическое воплощение идея самодвижущегося экипажа получила в 1769 году, когда французский военный инженер Николя-Жозеф Кюньо (Nicolas-Joseph Cugnot) по заказу военного ведомства Франции построил трехколесную тележку с паровым двигателем (fardier à vapeur). Данный аппарат предназначен был для транспортировки тяжелых артиллерийских орудий. Двухцилиндровый паровой двигатель прямого действия приводил во движение переднее единственное колесо, которое выполняло роль как ведущего, так и рулевого элементов. Скорость движения не превышала 3.5–4 км/ч, а запас хода по запасу пара составлял около 15 минут, после чего требовалась перезаправка котла водой и топливом.")

    add_heading_2(doc, "1.2 Паровые дилижансы и инженерные барьеры паровой тяги")
    add_paragraph(doc, "В первой половине XIX века центр развития парового автотранспорта сместился в Великобританию и Францию. Изобретатели Ричард Тревитик (1801 г.) и Голдуорти Герни (1820-е гг.) успешно эксплуатировали паровые экипажи и пассажирские дилижансы. Паровой транспорт Герни развивал скорость до 20 км/ч и мог перевозить до 18 пассажиров.")
    add_paragraph(doc, "Однако расширению парового автомобилестроения помешал ряд критических научно-технических и социально-правовых барьеров. Паровые машины обладали чрезвычайно высокой цепной массой, громоздким котлом, низким КПД (менее 5-8%) и требовали длительного времени для поднятия рабочего давления пара. В 1865 году в Великобритании был принят закон «Locomotive Act» (известный как «Закон Red Flag»), предписывавший, чтобы перед каждым механическим экипажем на расстоянии 60 ярдов шел человек с красным флагом и предупреждал прохожих, ограничивая скорость до 3 км/ч в городах. Это законодательное ограничение затормозило развитие сухопутного безрельсового транспорта на десятилетия.")
    doc.add_page_break()

    # 5. ГЛАВА 2
    add_heading_1(doc, "Глава 2. Изобретение ДВС и становление массового автопрома (1886–1930-е гг.)")
    add_heading_2(doc, "2.1 Создание ДВС и патенты Карла Бенца и Готтлиба Даймлера")
    add_paragraph(doc, "Решающий прорыв в истории транспорта произошел с созданием компактного и эффективного двигателя внутреннего сгорания (ДВС). После разработок Этьена Ленуара (газовый ДВС, 1860 г.) и Николауса Отто (четырехтактный цикл, 1876 г.) немецкие инженеры адаптировали ДВС для использования жидкого нефтяного топлива (бензина).")
    add_paragraph(doc, "29 января 1886 года Карл Бенц получил германский патент № DRP-37435 на «экипаж с двигателем, работающим на бензине» (Benz Patent-Motorwagen). Данное транспортное средство представляло собой специально сконструированный трехколесный экипаж с трубчатой стальной рамой, одноцилиндровым четырехтактным двигателем объемом 954 куб. см и мощностью 0.75 л.с., водяным охлаждением, электрическим зажиганием и ременной передачей. 1886 год официально признан годом рождения современного автомобиля.")
    add_paragraph(doc, "Параллельно Готтлиб Даймлер и Вильгельм Майбах в Каннштатте разработали высокооборотный бензиновый двигатель («Дедушкины часы») и установили его в 1885 году на деревянный двухколесный экипаж (первый мотоцикл Reitwagen), а в 1886 году — на четырехколесную карету. Исторический пробег Берты Бенц (жены Карла Бенца) в августе 1888 года на расстояние около 106 км из Мангейма в Пфорцхайм доказал коммерческую и практическую состоятельность автомобильного транспорта.")

    add_heading_2(doc, "2.2 Генри Форд, конвейерная революция и доступность автомобиля")
    add_paragraph(doc, "До начала XX века автомобиль оставался штучным, дорогостоящим предметом роскоши, собиравшимся высококвалифицированными ремесленниками вручную. Ситуация кардинально изменилась с появлением американского промышленника Генри Форда (Henry Ford).")
    add_paragraph(doc, "В 1908 году Ford Motor Company представила модель Ford Model T («Жестяная Лиззи»). Автомобиль отличался простой, прочной конструкцией с 4-цилиндровым двигателем мощностью 20 л.с., планетарной коробкой передач и высоким дорожным просветом. Однако главным новшеством Форда стало внедрение в 1913 году на заводе в Хайленд-Парке движущегося сборочного конвейера. Время сборки шасси сократилось с 12 часов 8 минут до 93 минут, что позволило снизить розничную цену автомобиля с $850 в 1908 году до $260 к 1925 году. До 1927 года было произведено более 15 миллионов экземпляров Ford Model T, что сделало автомобиль массовым и доступным средством передвижения.")
    doc.add_page_break()

    # 6. ГЛАВА 3
    add_heading_1(doc, "Глава 3. Золотой век, безопасность и технологическая эволюция (1940–1990-е гг.)")
    add_heading_2(doc, "3.1 Развитие систем безопасности и аэродинамики кузова")
    add_paragraph(doc, "В середине XX века ключевыми факторами проектирования автомобилей стали аэродинамика и безопасность. Немецкий инженер Бела Барени (Béla Barényi), работая в компании Mercedes-Benz, в 1951 году запатентовал концепцию пассивной безопасности с жестким каркасом салона (ячейкой безопасности) и фронтальными/задними деформируемыми зонами сминания (crumple zones), поглощающими энергию удара при столкновении.")
    add_paragraph(doc, "В 1959 году шведский инженер Нильс Болин (Nils Bohlin), работавший в компании Volvo, изобрел трехточечный ремень безопасности. Volvo открыла патент для всех автопроизводителей, что спасло миллионы жизней. Позже появились антиблокировочная система тормозов (ABS, внедренная в серию Bosch и Mercedes-Benz в 1978 году) и подушки безопасности (Airbag), сформировавшие современный комплекс активной и пассивной безопасности.")

    add_heading_2(doc, "3.2 Нефтяной кризис 1973 года, электронное управление и рост японского автопрома")
    add_paragraph(doc, "Мировой энергетический кризис 1973 года привела к резкому росту цен на нефть и кардинально перестроила требования к автомобилям. Американские «маслкары» с многолитровыми карбюраторными двигателями уступили долю рынка компактным и экономичным японским автомобилям (Toyota, Honda, Nissan).")
    add_paragraph(doc, "Японские компании продемонстрировали преимущество Производственной системы Toyota (TPS, Lean Manufacturing), обеспечивающей высочайшее качество и низкую себестоимость. С технической точки зрения 1980–1990-е годы ознаменовались массовым отказом от карбюраторов в пользу микропроцессорных систем инжекторного впрыска топлива, применением каталитических нейтрализаторов выхлопных газов, электронных блоков управления двигателем (ECU) и бортовой диагностики OBD-II.")
    doc.add_page_break()

    # 7. ГЛАВА 4
    add_heading_1(doc, "Глава 4. Современные тренды: Электрификация, цифра и автопилоты (XXI век)")
    add_heading_2(doc, "4.1 Ренессанс электромобилей и архитектура бета-платформ")
    add_paragraph(doc, "В XXI веке экологические стандарты (Euro-6, CAFE) и изменение климатической повестки подтолкнули автопром к декарбонизации. Несмотря на то что электромобили существовали еще на рубеже XIX–XX веков (экипажи Томаса Паркера, Лонера-Порше и др.), их массовое возвращение стало возможным благодаря развитию литий-ионных аккумуляторных батарей (Li-ion).")
    add_paragraph(doc, "Выход на рынок компании Tesla (модели Roadster в 2008 г. и Model S в 2012 г.) перевернул представление об электромобилях. Современный электромобиль строится на специализированной платформе типа «скейтборд» (Flat Battery Pack Architecture), где тяговый аккумулятор интегрирован в силовую структуру пола, обеспечивая низкий центр тяжести и оптимальное распределение массы. В 2020-х годах к лидерству в сфере электротранспорта присоединились китайские концерны (BYD, CATL), внедряющие инновационные фосфатные (LFP) и твердотельные аккумуляторы.")

    add_heading_2(doc, "4.2 Автономное вождение (SAE 0-5) и программно-определяемый автомобиль (SDV)")
    add_paragraph(doc, "Параллельно с электрификацией происходит трансформация автомобиля в программно-определяемый объект (Software-Defined Vehicle, SDV). Бортовая архитектура переходит от множества изолированных контроллеров к централизованным мощным вычислительным платформам и зональным контроллерам.")
    add_paragraph(doc, "Согласно стандарту SAE J3016, автономность транспортных средств разделена на 6 уровней (от 0 — отсутствие автоматизации, до 5 — полная автономность без участия человека). Системы помощи водителю ADAS (Level 2/2+) включают адаптивный круиз-контроль, удержание в полосе и автопарковку. Ведущие разработчики (Waymo, Cruise, Baidu, Tesla FSD) активно тестируют системы 3 и 4 уровней автономности, применяющие комплексы лидаров, радаров, радар-детекторов, ультразвуковых датчиков и глубоких нейронных сетей для распознавания дорожной обстановки в real-time.")
    doc.add_page_break()

    # 8. ЗАКЛЮЧЕНИЕ
    add_heading_1(doc, "Заключение")
    add_paragraph(doc, "В ходе проведенного исследования истории развития автомобилестроения сформированы следующие основные выводы:")
    add_paragraph(doc, "1. Эволюция автомобильного транспорта прошла путь от экспериментальных паровых платформ XVIII века до высокоэффективных транспортных систем. Главным катализатором первого этапа стало изобретение бензинового ДВС (К. Бенц, Г. Даймлер, 1886 г.).")
    add_paragraph(doc, "2. Внедрение Генри Фордом сборочного конвейера в 1913 году трансформировало автомобиль из предмета роскоши в доступный массовый продукт, создав современную структуру мировой автомобильной промышленности.")
    add_paragraph(doc, "3. Вторая половина XX века была ознаменована повышением системной безопасности (деформируемые зоны М. Барени, 3-точечные ремни Н. Болина) и внедрением микропроцессорной электроники для снижения вредных выбросов и расхода топлива.")
    add_paragraph(doc, "4. На современном этапе (XXI в.) автопром переживает третью технологическую революцию, определяемую сдвигом в сторону электрической тяги (BEV), цифровых программно-определяемых платформ (SDV) и беспилотных систем вождения (ADAS/Autonomous Driving). Автомобиль перестает быть чисто механическим устройством и становится интеллектуальным узлом мультимодальной транспортной сети будущего.")
    doc.add_page_break()

    # 9. СПИСОК ЛИТЕРАТУРЫ
    add_heading_1(doc, "Список использованных информационных источников")
    add_paragraph(doc, "1. Аллен, Т. История автомобилестроения и инженерной мысли / Т. Аллен. — М. : Машиностроение, 2019. — 412 с.")
    add_paragraph(doc, "2. Бенц, К. Жизнь инженера: воспоминания и изобретения / К. Бенц. — СПб. : Политехника, 2017. — 254 с.")
    add_paragraph(doc, "3. Вульфсон, Г. Н. История техники и транспорта : учебник для вузов / В. Н. Вульфсон. — 2-е изд. — М. : Юрайт, 2021. — 380 с.")
    add_paragraph(doc, "4. Форд, Г. Моя жизнь, мои достижения / Г. Форд ; пер. с англ. — М. : АСТ, 2022. — 352 с.")
    add_paragraph(doc, "5. SAE International. Taxonomy and Definitions for Terms Related to Driving Automation Systems for On-Road Motor Vehicles (SAE J3016_202104) / SAE International. — Warrendale : SAE, 2021. — 41 p.")
    add_paragraph(doc, "6. Eckermann, E. World History of the Automobile / E. Eckermann. — Warrendale : Society of Automotive Engineers (SAE), 2001. — 371 p.")
    add_paragraph(doc, "7. Toyota Production System: Beyond Large-Scale Production / T. Ohno. — Cambridge : Productivity Press, 1988. — 143 p.")

    return save_report(doc, "Доклад_История_автомобилей.docx")


if __name__ == "__main__":
    generate()
